// 四个工艺小游戏的数据：辨纹点位与轮次、织绸色带、染缸染谱
// 辨纹扎线（p01 杏花卷草）：节点坐标为正方形棋盘百分比，全部取自蓝本纹样的真实线条，
// 由 tools/check_thread_nodes.py 叠加蓝本图逐点核验。
//  R1 外轮廓走向：沿中央主花红色外轮廓绕一圈（起=终=花顶尖，闭合环）；
//  R2 中间纹路接入：底菱形→主茎→左右托叶（先左/先右两种等价走法）→花内蓝色水滴；
//  R3 末端回折位置：左小花→左卷草小钩与大涡→跨主茎→右卷草双涡→右小花。
//  threadDecoCoords 为干扰点：同样落在装饰纹（菱形/小涡心/叶尖/邻花）上，但不属于任何一轮走线。
const threadRoundCoords=[
 // R1 外轮廓（末尾回到花顶尖，闭合）
 [[50.0,18.5],[44.7,23.2],[39.1,28.7],[33.5,33.5],[30.3,37.5],[31.9,44.7],[37.5,48.6],[44.7,51.0],[50.0,52.2],[55.4,51.0],[62.6,48.6],[68.3,44.7],[70.2,37.5],[66.6,33.5],[61.0,28.7],[55.4,23.2],[50.0,18.5]],
 // R2 中间纹路（先左托叶）
 [[50.0,94.9],[50.0,83.7],[50.0,76.6],[50.0,69.2],[50.0,63.8],[44.3,55.8],[47.8,62.2],[50.0,57.4],[55.8,55.8],[52.2,62.2],[50.0,52.2],[50.0,43.1],[50.0,35.9],[50.0,27.9]],
 // R3 末端回折
 [[19.5,33.5],[11.2,38.7],[19.5,50.2],[11.2,59.0],[21.5,68.5],[31.5,68.6],[31.0,71.0],[37.5,71.8],[34.9,76.6],[37.5,83.7],[44.3,82.1],[43.5,76.6],[44.7,71.0],[50.0,69.2],[55.3,71.0],[56.5,76.6],[55.7,82.1],[62.5,83.7],[65.1,76.6],[62.5,71.8],[69.0,71.0],[68.5,68.6],[78.5,68.5],[88.8,59.0],[80.5,50.2],[88.8,38.7],[80.5,33.5]]];
// R2 等价走法：先右托叶后左托叶（与 R2 仅托叶访问顺序不同）
const threadAltCoords=[[50.0,94.9],[50.0,83.7],[50.0,76.6],[50.0,69.2],[50.0,63.8],[55.8,55.8],[52.2,62.2],[50.0,57.4],[44.3,55.8],[47.8,62.2],[50.0,52.2],[50.0,43.1],[50.0,35.9],[50.0,27.9]];
// 干扰点（装饰纹样上的点，任何轮次点击都判错）
const threadDecoCoords=[[50.0,8.0],[4.4,50.2],[95.6,50.2],[27.9,75.8],[72.1,75.8],[13.2,26.3],[86.8,26.3],[23.9,9.6],[76.1,9.6],[4.8,75.8],[95.2,75.8]];
// 合并去重生成节点表（坐标四舍五入到 0.1%），再把坐标序列翻译成节点索引序列
(function(){
 const key=p=>p[0].toFixed(1)+','+p[1].toFixed(1);
 const nodes=[], index={};
 const intern=p=>{const k=key(p);
  if(!(k in index)){index[k]=nodes.length;nodes.push(p)}
  return index[k];};
 const seqs0=threadRoundCoords.map(seq=>seq.map(intern));
 const alt0=threadAltCoords.map(intern);
 threadDecoCoords.forEach(intern);
 window.threadNodes=nodes;
 window.threadRounds=seqs0;
 window.threadVariants=seqs0.map((seq,r)=>r===1?[seq,alt0]:[seq]);
})();
const weaveColors=['#648ca8','#b95c55','#dec46c'];
const vats=[
 {key:'blue',title:'蓝缸 · 浅蓝打底',zones:[[.28,.55]],labels:['浅蓝'],color:'#648ca8',stages:1,desc:'浸入后让浅蓝进入经线，在“浅蓝”区间取出。'},
 {key:'red',title:'红缸 · 两次叠色',zones:[[.25,.48],[.6,.82]],labels:['打底','叠色'],color:'#b95c55',stages:2,desc:'先打底红，再一次叠色：两次都要落在各自区间。'},
 {key:'yellow',title:'黄缸 · 色晕取线',zones:[[.56,.76]],labels:['色晕'],color:'#dec46c',stages:1,desc:'等浅色晕刚形成时取线；过早不匀，过晚会发闷。'}
];
